				\begin{document}$$\:\frac{\text{d}{N}_{H}\left(t\right)}{\text{d}t}={k}_{H}\left({T}_{ref}\right)\cdot\:{10}^{\frac{T\left(t\right)-{T}_{ref}}{{z{\prime\:}}_{H}}}\text{w}\text{i}\text{t}\text{h}\:{N}_{H}\left(t=0\right)={N}_{H0}\:$$\end{document}4\documentclass[12pt]{minimal}
